package com.terravow.reasoning;

import java.util.Objects;

/**
 * A declaration of a verified deterministic tool a specialist agent may invoke via Gemini function
 * calling (Req 2.2, 4.5, 6.2, 6.5, 11.1).
 *
 * <p>The declaration names the tool ({@link ToolId}) and the {@link Schema}s of its input and
 * output. The tool is <em>executed by TerraVow, not free-generated by the model</em>: the model
 * returns a structured call and TerraVow runs the verified computation (EC formula, ERD summation,
 * mass-preservation check, net-position arithmetic) and feeds the result back. This preserves the
 * deterministic-first principle — the model orchestrates, verified tools emit the numbers.
 *
 * @param id     the tool identifier; never {@code null}
 * @param input  the schema of the tool's input arguments; never {@code null}
 * @param output the schema of the tool's result; never {@code null}
 *
 * @see <a href="file:../../../../../.kiro/specs/terravow/requirements.md">Req 2.2, 4.5, 6.2, 6.5,
 *      11.1</a>
 */
public record ToolDeclaration(ToolId id, Schema input, Schema output) {

    /**
     * Validates that the identifier and both schemas are present.
     *
     * @throws NullPointerException if {@code id}, {@code input}, or {@code output} is {@code null}
     */
    public ToolDeclaration {
        Objects.requireNonNull(id, "ToolDeclaration id must not be null");
        Objects.requireNonNull(input, "ToolDeclaration input schema must not be null");
        Objects.requireNonNull(output, "ToolDeclaration output schema must not be null");
    }
}
